const $=id=>document.getElementById(id), tr=(en,pt)=>lang==='pt'?pt:en;
let lang='en',mode='duel',opponent='bot',dictionaries={},state=null,local=null,remote=false,code='',draft='',busy=false,polling=false,offset=0,botDue=0,botRound='',lastBoard='',lastAnnouncement='',lastKeys='',revision=-1,connectionOk=true;
let resultDismissed=false,roomRetryAt=0,searchRetryAt=0;
let intent=null,searchQueue=null;let accountRender=()=>{},step="modes",signedAccount=null,loaded=false,search=null,searchBusy=false,cancelling=false;
const preferences=(()=>{try{const value=JSON.parse(localStorage.getItem('lexivanto-preferences'));return value&&typeof value==='object'&&!Array.isArray(value)?value:{};}catch{return {};}})();
const onlinePreferences=preferences.online&&typeof preferences.online==='object'?preferences.online:{};
const matchPreferences=preferences.matches&&typeof preferences.matches==='object'?preferences.matches:{};
if(!preferences.friendlyUntimedDefault){for(const rule of Object.values(matchPreferences))if(rule&&typeof rule==='object')rule.seconds=0;preferences.friendlyUntimedDefault=true;}
function remember(){preferences.lang=lang;preferences.mode=mode;preferences.opponent=opponent;preferences.name=$('nickname').value;preferences.matches=matchPreferences;preferences.online=onlinePreferences;matchPreferences[mode]=config(false);try{localStorage.setItem('lexivanto-preferences',JSON.stringify(preferences));}catch{}}
const feedback=createFeedback();
const practiceResults=new Set();let practiceWins=0,practicePlayed=0;
const errors={account_active:['This account is already searching in another tab. Cancel that search there, or wait a few seconds after closing it.',''],username_reserved:['That username is reserved. Choose another name, or sign in to the account that owns it.','Escolhe outro nome.'],rate_limited:['Too many requests. Wait one minute and try again.','Demasiados pedidos. Aguarda um minuto e tenta novamente.'],opponent_left:['Your opponent left. Choose a new game.','O adversário saiu. Escolhe outro jogo.'],stale_match:['The match changed. Check the current game and try again.','A partida mudou. Verifica o jogo atual e tenta novamente.'],five_letters:['Enter a five-letter word.','Escreve uma palavra com cinco letras.'],unknown_word:['Not in this preview’s dictionary. Try another word.','Não está no dicionário desta versão. Experimenta outra palavra.'],repeated:['That word is already on your board.','Essa palavra já está no teu tabuleiro.'],locked:['Your guess is locked. Wait for the reveal.','A tua tentativa está confirmada. Aguarda a revelação.'],not_turn:['It’s your partner’s turn.','É a vez do teu parceiro.'],room_full:['This room already has two players or has started.','Esta sala já tem dois jogadores ou já começou.'],room_expired:['Room not found or expired. Check the code or create a new room.','Sala não encontrada ou expirada. Verifica o código ou cria outra sala.'],room_access:['Join using the room code to take a player seat.','Entra com o código da sala para ocupar um lugar.'],session:['The browser session could not be restored. Rejoin the room.','Não foi possível restaurar a sessão. Volta a entrar na sala.'],busy:['The room changed at the same time. Please try again.','A sala foi alterada ao mesmo tempo. Tenta novamente.'],not_playing:['This match is no longer in progress.','Esta partida já não está em curso.'],not_waiting:['The match has already started.','A partida já começou.'],sign_in_required:['Sign in to play Competitive. Normal games are open to everyone.',''],online_duel_only:['The public queue is Duel only. Choose Friends for Race, Co-op or Word swap.',''],storage_unavailable:['Room service is temporarily unavailable. Your word is kept; try again.','O serviço de salas está temporariamente indisponível. A tua palavra foi mantida; tenta novamente.']};
function message(where,e){$(where).textContent=errors[e]?tr(...errors[e]):e;if(where==='game-error')$('result-error').textContent=$(where).textContent;}
function stored(key){try{return sessionStorage.getItem(key);}catch{return null;}}
function save(key,value){try{value===null?sessionStorage.removeItem(key):sessionStorage.setItem(key,value);}catch{}}
let token=stored('cw-player-token');if(!token){token=Array.from(crypto.getRandomValues(new Uint8Array(32))).map(n=>n.toString(16).padStart(2,'0')).join('');save('cw-player-token',token);}
function matchKind(){if(!state)return{key:'practice',label:'PRACTICE · NOT RATED',note:'Practice games never change your rating.'};if(!remote)return{key:'practice',label:'PRACTICE · NOT RATED',note:'Practice games never change your rating.'};if(!state.online)return{key:'friend',label:'FRIEND GAME · NOT RATED',note:'Friend games never change your rating.'};if(state.queue==='normal')return{key:'online',label:'NORMAL · NOT RATED',note:'Normal games never change your rating.'};const mine=state.players[state.me]?.tag,theirs=state.players[1-state.me]?.tag;if(mine&&theirs&&mine!==theirs)return{key:'rated',label:'COMPETITIVE · RATED',note:'Rated: your Duel rating changes with this result.'};return{key:'online',label:'ONLINE · NOT RATED',note:mine?'Not rated: your opponent is playing as a guest.':'Not rated: sign in to play rated Duels.'};}
function deepScreen(){return !!state||!!search||step!=='modes';}
function syncHistory(){try{if(deepScreen()&&!history.state?.lexivanto)history.pushState({lexivanto:1},'',location.href);}catch{}}
try{addEventListener('popstate',()=>{const open=[...document.querySelectorAll('dialog[open]')].at(-1);if(open)open.close();else if(deepScreen())back();setTimeout(syncHistory,0);});}catch{}
function track(event){try{if(!token)return;fetch('/api/event',{method:'POST',keepalive:true,headers:{authorization:'Bearer '+token,'content-type':'application/json'},body:JSON.stringify({event})}).catch(()=>{});}catch{}}
function trackVisit(){try{const today=new Date().toISOString().slice(0,10);if(localStorage.getItem('lexivanto-visit')===today)return;localStorage.setItem('lexivanto-visit',today);track('visit');}catch{}}
const trackedMatches=new Set();function trackFinish(){if(!state||state.status!=='finished'||state.reason==='cancelled')return;const key=(code||local?.created||'p')+':'+state.match;if(trackedMatches.has(key))return;trackedMatches.add(key);track(!remote?'practice_finished':state.online?'online_finished':'friend_room_finished');}
function shakeDraft(){const row=$('draft-row');row.classList.remove('shake');void row.offsetWidth;row.classList.add('shake');}
function modeName(m=mode){return ({duel:tr('Duel','Duelo'),race:tr('Race','Corrida'),coop:tr('Co-op','Cooperação'),swap:'Word swap'})[m];}
function config(forPlay=true){return settings({mode,lang,clockMode:mode==='duel'?'response':'round',difficulty:$('difficulty').value,seconds:forPlay&&opponent==='bot'?0:Number($('clock').value),sudden:false,attempts:Number($('attempts').value)});}
function onlineRules(){return onlineSettings(mode,lang,onlinePreferences[mode]);}
function onlineTiming(){$('online-description').textContent=(signedAccount?'Rated Duel · ':'Not rated as a guest · ')+clockText(onlineRules());}
function applyTheme(value){const theme=value==='light'?'light':'dark';preferences.theme=theme;document.documentElement.dataset.theme=theme;$('theme-button').textContent=theme==='dark'?tr('Light mode','Modo claro'):tr('Dark mode','Modo escuro');$('theme-button').setAttribute('aria-pressed',String(theme==='dark'));}
function clockText(s){if(!s.seconds)return tr('No time limit','Sem limite de tempo');if(s.mode==='duel'&&s.clockMode==='response')return tr(s.seconds+' s to reply',s.seconds+' s para responder');const unit=['race','swap'].includes(s.mode)?tr('match','partida'):s.mode==='coop'?tr('turn','turno'):tr('round','ronda');const time=s.seconds>=60&&['race','swap'].includes(s.mode)?(s.seconds/60)+' min':s.seconds+' s';return time+' / '+unit+(s.sudden?tr(' · after round 6',' · após a ronda 6'):'');}
function ruleText(s){if(s.mode==='swap')return 'Choose a five-letter word for each other. Both players finish. Fewer guesses wins; equal guesses are decided by solving time. No time limit. Not rated.';if(s.mode==='duel'&&s.clockMode==='response'&&!s.seconds)return tr('Both choose a word with no time limit. Lock your guess, then reveal both words together.','Ambos escolhem uma palavra sem limite de tempo. Confirma a tentativa e revelem as duas palavras em conjunto.');if(s.mode==='duel'&&s.clockMode==='response')return tr('Both choose a word. The first locked guess starts the other player’s response timer. Both guesses reveal after the reply. If you do not reply in time, your opponent wins.','Ambos escolhem uma palavra. A primeira confirmação inicia o tempo de resposta do outro jogador. As tentativas são reveladas após a resposta. Se não responderes a tempo, ganha o adversário.')+(s.seconds?'':tr(' This match has no time limit.',' Esta partida não tem limite de tempo.'));if(s.mode==='duel')return tr('Both players submit once per round. Both guesses reveal together. The first correct submission wins; equal server timestamps draw. No six-round limit.','Ambos enviam uma tentativa por ronda. As duas são reveladas em conjunto. Ganha a primeira resposta certa; se o servidor registar tempos iguais, há empate. Sem limite de seis rondas.');if(['race','swap'].includes(s.mode))return tr('Same word, separate boards. First correct guess wins. Play independently with unlimited guesses and no timer.','A mesma palavra, tabuleiros separados. Ganha quem usar menos tentativas; em caso de igualdade, decide o tempo. Quando um acerta, o outro ainda pode ganhar com menos tentativas.');return tr('Take turns on one shared board. Find the word together. ','Joguem à vez no mesmo tabuleiro. Descubram a palavra juntos. ')+(s.attempts?tr(`${s.attempts} total attempts.`,`${s.attempts} tentativas no total.`):tr('Unlimited attempts.','Tentativas sem limite.'))+(s.seconds?tr(' A timeout ends the team game.',' Se o tempo acabar, termina o jogo da equipa.'):'');}
function translate(){document.documentElement.lang=lang==='pt'?'pt-PT':'en';document.querySelectorAll('[data-en]').forEach(el=>el.textContent=el.dataset[lang==='pt'?'pt':'en']);$('language').value=lang;$('help').ariaLabel=tr('How to play','Como jogar');$('close-help').ariaLabel=tr('Close','Fechar');$('close-profile').ariaLabel=tr('Close profile','Fechar perfil');$('join-code').ariaLabel=tr('Room code','Código da sala');$('board').ariaLabel=tr('Word board','Tabuleiro de palavras');$('keyboard').ariaLabel=tr('Keyboard','Teclado');$('nickname').placeholder=tr('Your name','O teu nome');setup(false);applyTheme(preferences.theme);accountRender();if(state)render();else showStep(step,false);}
function setup(reset=true){$('choose-bot').hidden=mode==='swap';$('choose-online').hidden=mode!=='duel';$('search-bot').hidden=mode==='swap';const options=['race','swap'].includes(mode)?[0]:[0,15,30,60,120];if(reset){const prior=matchPreferences[mode]||{};$('clock').value=options.includes(prior.seconds)?prior.seconds:0;$('sudden').value=prior.sudden===false?'no':'yes';$('attempts').value=[0,6,10].includes(prior.attempts)?prior.attempts:6;$('difficulty').value=['easy','normal','expert'].includes(prior.difficulty)?prior.difficulty:'easy';}$('clock-buttons').replaceChildren();for(const sec of options){const button=document.createElement('button');button.textContent=sec===0?tr('No limit','Sem limite'):mode==='race'?`${sec/60} min`:`${sec} s`;button.dataset.clock=String(sec);button.onclick=()=>{$('clock').value=sec;updateSummary();remember();};$('clock-buttons').append(button);}$('clock-label').textContent=mode==='race'?tr('Match time','Tempo da partida'):mode==='coop'?tr('Time per turn','Tempo por turno'):tr('Time to reply','Tempo para responder');$('friend-settings').hidden=['race','swap'].includes(mode);$('attempt-field').hidden=mode!=='coop';$('sudden-field').hidden=true;onlineTiming();updateSummary();}
function difficultyName(value){return ({easy:tr('Easy','Fácil'),normal:tr('Medium','Médio'),expert:tr('Hard','Difícil')})[value]||tr('Easy','Fácil');}
function updateSummary(){const s=config(false);$('sudden-field').hidden=true;$('rules-summary').textContent=clockText(s)+(mode==='coop'?' · '+(s.attempts?tr(s.attempts+' attempts',s.attempts+' tentativas'):tr('Unlimited attempts','Tentativas sem limite')):'');document.querySelectorAll('[data-clock]').forEach(el=>el.setAttribute('aria-pressed',String(Number(el.dataset.clock)===s.seconds)));document.querySelectorAll('[data-setting]').forEach(el=>el.setAttribute('aria-pressed',String($(el.dataset.setting).value===el.dataset.value)));}
function menuControls(){const blocked=busy||cancelling||!loaded;document.querySelectorAll('[data-mode],[data-level],#choose-online,#choose-friend,#choose-bot,#create,#join').forEach(el=>el.disabled=blocked);$('profile-button').disabled=!!search||busy;$('back-button').hidden=!state&&!search&&step==='modes';$('menu-button').hidden=true;$('back-button').textContent='← Back';const backDestination=state?(state.status==='finished'?'Back to game modes':'Back · confirm leaving this match'):search?'Back to opponent choice · cancel search':['bot','friend'].includes(step)?'Back to opponent choice':'Back to game modes';$('back-button').setAttribute('aria-label',backDestination);$('back-button').title=backDestination;$('menu-button').textContent=state&&state.status!=='finished'?(remote?tr('Leave match','Sair da partida'):tr('End practice','Terminar treino')):search?tr('Cancel search','Cancelar procura'):tr('Game modes','Modos de jogo');$('search-bot').disabled=cancelling;$('cancel-search').textContent=cancelling?tr('Cancelling…','A cancelar…'):search&&!search.legacy?'Cancel search':tr('Cancel · Change opponent','Cancelar · Mudar adversário');$('search-bot').hidden=mode==='swap'||search?.queue==='ranked';$('back-button').disabled=busy||cancelling;$('menu-button').disabled=busy||cancelling;}
function showStep(next,focus=true){resultDismissed=false;if($('result').open)$('result').close();document.body.classList.remove('playing');step=next;setTimeout(syncHistory,0);$('join-section').hidden=step!=='invite';$('menu').hidden=false;$('game-layout').hidden=true;if(next==='modes'){intent=null;searchQueue=null;}if(document.body.dataset)document.body.dataset.step=next;for(const page of ['modes','games','competitive','opponent','bot','friend','search'])$('step-'+page).hidden=step==='invite'?!['opponent','friend'].includes(page):page!==step;$('opponent-options').hidden=step==='invite';$('online-settings').hidden=true;$('friend-create').hidden=step==='invite';$('friend-heading').hidden=step==='invite';$('opponent-heading').textContent=step==='invite'?tr('Join your friend','Junta-te ao teu amigo'):modeName()+tr(' · Play with…',' · Jogar com…');$('bot-heading').textContent=modeName()+tr(' · Choose a bot',' · Escolhe um bot');$('friend-heading').textContent=modeName()+tr(' · Invite a friend',' · Convida um amigo');$('online-description').textContent=(signedAccount?'Rated Duel · ':'Not rated as a guest · ')+clockText(onlineRules());$('guest-name-field').hidden=!!signedAccount;$('signed-name').hidden=!signedAccount;$('signed-name').textContent=tr('Playing as ','A jogar como ')+(signedAccount?.name||'');renderActivity();menuControls();if(focus){const heading=$(step==='modes'?'modes-heading':step==='games'?'games-heading':step==='competitive'?'competitive-heading':['opponent','invite'].includes(step)?'opponent-heading':step==='bot'?'bot-heading':step==='friend'?'friend-heading':'search-heading');heading.focus();}}
function chooseMode(value){if(busy||!loaded)return;remember();mode=value;setup();message('menu-error','');if(intent){chooseOpponent(intent);return;}showStep('opponent');}
function validName(){if(signedAccount)$('nickname').value=signedAccount.name;if(!$('nickname').value.trim()){const n=new Uint16Array(1);crypto.getRandomValues(n);$('nickname').value='Player '+String(1000+n[0]%9000);}remember();message('menu-error','');return true;}
function chooseOpponent(value){if(mode==='swap'&&value!=='friend')return;if(busy||!loaded||!validName())return;opponent=value;remember();if(value==='online'){startSearch();return;}showStep(value==='bot'?'bot':'friend');}
async function queueApi(action,body){const r=await fetch('/api/matchmaking/'+action,{method:'POST',headers:{authorization:'Bearer '+token,'content-type':'application/json'},body:JSON.stringify(body),signal:AbortSignal.timeout(12000)});let data;try{data=await r.json();}catch{throw Error('storage_unavailable');}if(!r.ok){const error=Error(data.error||'storage_unavailable');error.status=r.status;if(r.status===429)searchRetryAt=Date.now()+Math.max(1000,Math.min(300000,Number(r.headers.get('retry-after')||60)*1000));throw error;}return data;}
function startSearch(restored){if(search||busy)return;search=restored||{seconds:onlineRules().seconds,searchId:Array.from(crypto.getRandomValues(new Uint8Array(16))).map(x=>x.toString(16).padStart(2,'0')).join(''),mode,lang,name:$('nickname').value.trim(),queue:searchQueue||(signedAccount?'ranked':'normal'),legacy:!searchQueue,started:Date.now()};save('lexivanto-search',JSON.stringify(search));showStep('search');$('search-detail').textContent=(search.queue==='ranked'?'Competitive · rated':'Normal · not rated')+' · '+modeName(search.mode)+' · '+clockText(onlineRules());$('search-heading').textContent=search.queue==='ranked'?'Finding a rated opponent…':'Finding a player…';searchPoll();}
async function searchPoll(){if(!search||searchBusy||cancelling||Date.now()<searchRetryAt||document.hidden)return;searchBusy=true;const current=search;try{const data=await queueApi('search',current);if(search!==current||cancelling)return;message('menu-error','');if(data.status==='matched'){search=null;save('lexivanto-search',null);remote=true;connectionOk=true;revision=-1;code=data.room.code;save('cw-room',code);draft='';adopt(data.room);translate();if(state.status==='waiting')await action('ready');}else if(data.status==='cancelled'){const from=current.legacy||!current.queue?'opponent':current.queue==='ranked'?'competitive':'modes';search=null;save('lexivanto-search',null);showStep(from);}}catch(e){if(search===current&&!cancelling&&e.message==='sign_in_required'){search=null;save('lexivanto-search',null);showStep('competitive');message('menu-error','sign_in_required');}else if(search===current&&!cancelling&&e.message==='account_active'){search=null;save('lexivanto-search',null);showStep('opponent');message('menu-error','account_active');}else if(search===current&&!cancelling&&e.status===429)message('menu-error','Search paused briefly. It will retry automatically; you can still cancel.');else if(search===current&&!cancelling)message('menu-error',tr('Search connection interrupted. Retrying… You can cancel below.','A ligação foi interrompida. A tentar novamente… Podes cancelar abaixo.'));}finally{searchBusy=false;}}
async function cancelSearch(destination='opponent'){if(!search||cancelling)return;if(destination==='opponent'&&search.queue&&!search.legacy)destination=search.queue==='ranked'?'competitive':'modes';cancelling=true;const current=search;$('cancel-search').disabled=true;menuControls();try{const data=await queueApi('cancel',current);if(data.status==='matched'){const r=await fetch('/api/rooms/'+data.room.code+'/leave',{method:'POST',headers:{authorization:'Bearer '+token,'content-type':'application/json'},body:JSON.stringify({match:data.room.match}),signal:AbortSignal.timeout(12000)});if(!r.ok)throw Error('storage_unavailable');}search=null;save('lexivanto-search',null);message('menu-error','');showStep(destination);}catch{message('menu-error',tr('Could not confirm cancellation. Try Cancel search again.','Não foi possível confirmar o cancelamento. Tenta cancelar novamente.'));}finally{cancelling=false;$('cancel-search').disabled=false;menuControls();}}
function back(){if(search){cancelSearch('opponent');return;}if(state){requestMenu();return;}if(busy)return;if(step==='games'||step==='competitive'){showStep('modes');return;}if(['bot','friend'].includes(step)&&intent){message('menu-error','');showStep('games');return;}if(step==='invite')history.replaceState(null,'',location.pathname);message('menu-error','');showStep(['bot','friend'].includes(step)?'opponent':'modes');}
async function api(action='',body){const response=await fetch(action==='create'?'/api/rooms':`/api/rooms/${code}${action?'/'+action:''}`,{method:body?'POST':'GET',headers:{authorization:'Bearer '+token,...(body?{'content-type':'application/json'}:{})},signal:AbortSignal.timeout(12000),...(body?{body:JSON.stringify({...(['guess','ready','leave','rematch','settings','choose-word','give-up'].includes(action)?{match:state?.match}:{}),...body})}:{})});let data;try{data=await response.json();}catch{throw Error('storage_unavailable');}if(!response.ok){if(response.status===429)roomRetryAt=Date.now()+Math.max(1000,Math.min(300000,Number(response.headers.get('retry-after')||60)*1000));if(data.error==='stale_match'&&data.room)adopt(data.room);const error=Error(data.error||'storage_unavailable');error.status=response.status;throw error;}return data;}
function adopt(data){if(data.code&&data.code!==code){$('invitation-link').value='';$('invite-sent').textContent='';}if(data.settings.lang!=='en')throw Error('This version supports English games only. Please start a new game.');if(remote&&data.revision!==undefined&&data.revision<revision)return;revision=data.revision??revision;offset=data.now-Date.now();state=data;code=data.code||code;lang=data.settings.lang;$('language').value=lang;render();}
function chooseAnswer(s,old){const list=dictionaries[s.lang].answers.filter(x=>x!==old);return list[Math.floor(Math.random()*list.length)];}
async function create(){if(busy||!validName())return;remember();busy=true;menuControls();$('create').disabled=true;message('menu-error','');try{const s=config();draft='';lastBoard='';revision=-1;$('invite-sent').textContent='';$('copy-link').textContent='Copy invitation link';if(opponent==='bot'){remote=false;code='';save('cw-room',null);local=makeRoom(s,$('nickname').value.trim()||tr('You','Tu'),'local',chooseAnswer(s));local.players[1]={name:'Milo',auth:'bot',ready:true};track('practice_started');state=view(local,0);render();await matchIntroduction();begin(local,Date.now());state=view(local,0);offset=0;botRound='';render();}else{remote=true;const data=await api('create',{settings:s,name:$('nickname').value});code=data.code;save('cw-room',code);adopt(data);}translate();$('board').focus();}catch(e){remote=false;message('menu-error',e.message);}finally{busy=false;$('create').disabled=false;if(state)render();menuControls();}}
async function joinRoom(value){if(busy||!validName())return;remember();let input=value.trim();try{if(input.includes('://'))input=new URL(input).searchParams.get('room')||'';}catch{}const room=input.replace(/\s/g,'').toUpperCase();if(!/^[A-F0-9]{12}$/.test(room)){message('menu-error',tr('Enter the 12-character room code.','Introduz o código de 12 caracteres.'));return;}busy=true;menuControls();$('join').disabled=true;try{remote=true;code=room;revision=-1;const info=await api('info');if(info.settings.lang!=='en')throw Error('This version supports English games only. Please create a new room.');const data=await api('join',{name:$('nickname').value});draft='';save('cw-room',code);adopt(data);translate();history.replaceState(null,'',location.pathname);}catch(e){remote=false;code='';message('menu-error',e.message);}finally{busy=false;$('join').disabled=false;if(state)render();menuControls();}}
function canType(){if(state?.settings.mode==='swap'){return state.status==='playing'&&!busy&&(state.started?!state.solved[state.me]&&!state.gaveUp[state.me]:!state.wordChosen[state.me]);}if(!state||state.status!=='playing'||busy)return false;if(state.settings.mode==='duel')return !state.submitted[state.me];if(state.settings.mode==='coop')return state.turn===state.me;return !state.solved[state.me];}
// Reveal feedback has priority over the next round's empty/covered rows.
function keepLatestResultVisible(scroll,board,count,mode){
 if(!count){scroll.scrollTop=0;return;}
 const first=board.children[Math.max(0,count-(mode==='duel'?2:1))],last=board.children[count-1];
 if(!first||!last)return;
 const viewport=scroll.getBoundingClientRect(),top=first.getBoundingClientRect().top-viewport.top-8,bottom=last.getBoundingClientRect().bottom-viewport.bottom+8;
 if(top<0)scroll.scrollTop+=top;
 else if(bottom>0)scroll.scrollTop+=Math.min(top,bottom);
}
function shownRows(){return ['race','swap'].includes(state.settings.mode)?state.boards[state.me]:state.rows;}
