const rows=shownRows();feedback.observe({id:(code||local?.created||'practice')+':'+state.match,status:state.status,reason:state.reason,rows:rows.length,locked:!!state.submitted?.[state.me],won:state.winner===state.me||state.winner==='team'});const displayRows=[...rows];if(s.mode==='duel'&&!finished&&!waiting){for(let seat=0;seat<2;seat++)displayRows.push({word:'',player:seat,covered:!!state.submitted[seat]});}while(displayRows.length<2)displayRows.push({word:''});const boardKey=JSON.stringify([displayRows,lang]);if(boardKey!==lastBoard){const changedCount=!lastBoard||JSON.parse(lastBoard)[0].length!==displayRows.length;const scroll=$('board-scroll'),previousCount=lastBoard?JSON.parse(lastBoard)[0].filter(row=>row.word).length:0,previousResult=$('board').children[previousCount-1],viewport=scroll.getBoundingClientRect(),rect=previousResult?.getBoundingClientRect(),followingLatest=scroll.scrollHeight-scroll.scrollTop-scroll.clientHeight<80||!!(rect&&rect.bottom<=viewport.bottom+8&&rect.bottom>viewport.top);const revealFrom=lastBoard?previousCount:Infinity;lastBoard=boardKey;$('board').replaceChildren();displayRows.forEach((row,index)=>{const line=wordRow(row,p);if(row.colors&&index>=revealFrom){line.classList.add('reveal');let i=0;for(const tile of line.children)if(/\btile\b/.test(tile.className))tile.style?.setProperty?.('--i',i++);}$('board').append(line);});if(changedCount&&(followingLatest||rows.length<=2))requestAnimationFrame(()=>{if(lastBoard===boardKey)keepLatestResultVisible(scroll,$('board'),rows.length,s.mode);});}
