$('locked-message').hidden=true;$('locked-message').textContent=statusText();if(!finished)resultDismissed=false;$('view-result').hidden=!finished;if(!finished&&$('result').open)$('result').close();if(finished){$('result-title').textContent=resultTitle();$('result-detail').textContent=(state.reason==='timeout'?tr('Time ran out. ','O tempo acabou. '):state.reason==='left'?tr('Your opponent left. ','O adversário saiu. '):'')+tr('The word was ','A palavra era ')+String(state.answer||'').toUpperCase()+'.';$('rematch').disabled=busy||state.reason==='cancelled'||state.players.some(x=>x?.departed);if(state.players.some(x=>x?.departed))$('result-detail').textContent+=state.reason==='left'?tr(' Choose a new game.',' Escolhe outro jogo.'):tr(' Your opponent left. Choose a new game.',' O adversário saiu. Escolhe outro jogo.');}
