function key(k){if(!canType())return;feedback.unlock();const before=draft;if(k==='ENTER'){submit();return;}if(k==='BACKSPACE')draft=draft.slice(0,-1);else {const n=normalize(k);if(/^[a-z]$/.test(n)&&draft.length<5)draft+=n;}if(draft!==before)feedback.play('tap');message('game-error','');render();}
async function submit(){if(!canType())return;if(remote&&Date.now()<roomRetryAt){message('game-error','Please wait '+Math.ceil((roomRetryAt-Date.now())/1000)+' seconds before submitting. Your word is kept.');return;}if(draft.length!==5){message('game-error','five_letters');feedback.play('error');shakeDraft();return;}if(!dictionaries[state.settings.lang].set.has(draft)){message('game-error','unknown_word');feedback.play('error');shakeDraft();return;}busy=true;try{if(remote){const data=await api(state.settings.mode==='swap'&&!state.started?'choose-word':'guess',{word:draft});draft='';adopt(data);}else{guess(local,0,draft,dictionaries[local.settings.lang].set,Date.now());draft='';state=view(local,0);}}catch(e){message('game-error',e.message);}finally{busy=false;render();}}
let introduction=null;const introducedMatches=new Set();
async function matchIntroduction(){if(introduction)return introduction;document.body.classList.add('match-introducing');introduction=new Promise(resolve=>setTimeout(resolve,1400));try{await introduction;}finally{document.body.classList.remove('match-introducing');introduction=null;}}
async function action(name){if(busy)return;busy=true;try{if(name==='ready'&&state.status==='waiting'){render();if(introduction)await introduction;}if(remote){const data=await api(name,{});draft='';adopt(data);}else if(name==='rematch'){rematch(local,0,chooseAnswer(local.settings,local.answer));local.players[1].ready=true;state=view(local,0);render();await matchIntroduction();ready(local,0,Date.now());draft='';lastBoard='';botRound='';state=view(local,0);}}catch(e){message('game-error',e.message);}finally{busy=false;render();}}
function menu(){setTimeout(()=>{try{friends.banner();}catch{}},0);if(busy)return;if(search){cancelSearch('modes');return;}feedback.observe(null);state=null;local=null;remote=false;code='';draft='';lastBoard='';lastKeys='';revision=-1;connectionOk=true;save('cw-room',null);$('language').disabled=false;message('menu-error','');history.replaceState(null,'',location.pathname);showStep('modes');}
