function requestMenu(){if(busy)return;if(search){cancelSearch('modes');return;}if(!state||state.status==='finished'){returnToModes();return;}const practice=!remote,waiting=state.status==='waiting';$('leave-title').textContent=practice?tr('End practice?','Terminar treino?'):waiting?tr('Leave this room?','Sair desta sala?'):tr('Leave this match?','Sair desta partida?');$('leave-detail').textContent=practice?tr('This practice ends. You’ll return to the game modes.','O treino termina. Voltas aos três modos de jogo.'):waiting?tr('You’ll leave the room and return to game modes.','Vais sair da sala e voltar aos modos de jogo.'):state.settings.mode==='coop'?tr('This ends the team game for both players. You’ll return to game modes.','O jogo termina para ambos. Voltas aos modos de jogo.'):tr('Your opponent wins if you leave now. You’ll return to game modes.','O adversário ganha se saíres agora. Voltas aos modos de jogo.');$('confirm-leave').textContent=practice?tr('End practice','Terminar treino'):tr('Leave match','Sair da partida');$('cancel-leave').textContent=waiting?tr('Stay in room','Ficar na sala'):tr('Keep playing','Continuar a jogar');$('leave-dialog').showModal();}
