function formatSolveTime(ms){const sec=Math.floor(ms/1000);return Math.floor(sec/60)+':'+String(sec%60).padStart(2,'0')+'.'+String(ms%1000).padStart(3,'0');}
function formatResultTime(ms){const sec=Math.floor(ms/1000);return Math.floor(sec/60)+':'+String(sec%60).padStart(2,'0')+'.'+Math.floor((ms%1000)/100);}
