function tick(){tickClock();if(search){const seconds=Math.max(0,Math.floor((Date.now()-search.started)/1000));$('search-elapsed').textContent=Math.floor(seconds/60)+':'+String(seconds%60).padStart(2,'0');$('search-wait').textContent=seconds<20?tr('Waiting for another player…','À espera de outro jogador…'):tr('Still searching. Another player must choose the same mode and language.','Ainda à procura. Outro jogador tem de escolher o mesmo modo e língua.');}if(remote||!local||local.status!=='playing')return;const now=Date.now();if(expire(local,now)){state=view(local,0);render();return;}const stamp=local.match+'-'+local.round+'-'+local.boards[1].length;if(stamp!==botRound){botRound=stamp;botDue=now+botDelay(local.settings.difficulty);}const botTurn=local.settings.mode==='duel'?!local.pending[1]:local.settings.mode==='coop'?local.turn===1:!local.solved[1];if(botTurn&&now>=botDue){const word=botWord(local,1,dictionaries[local.settings.lang].botWords||dictionaries[local.settings.lang].allowed);if(word){try{guess(local,1,word,dictionaries[local.settings.lang].set,now);}catch{botDue=now+2000;}state=view(local,0);render();}}}

