function paintPortrait(el,avatar,colour,name){const chosen=characterIds.includes(avatar);el.classList.toggle('character-picture',chosen);el.textContent=chosen?'':Array.from(name||'Player')[0].toUpperCase();el.style.backgroundPosition='';if(chosen)el.style.setProperty('--avatar-image','url(avatar-'+avatar+'.webp)');else el.style.removeProperty('--avatar-image');if(avatarColours.includes(colour))el.style.setProperty('--avatar-colour',colour);else el.style.removeProperty('--avatar-colour');}
const avatarColours=['#51d4ff','#f5b84c','#bba2ff','#71e2b1','#ff9d91','#8ebaff'];
