let liveActivity=null,activityBusy=false,activityFetched=0;
function renderActivity(){const fresh=liveActivity&&Date.now()-activityFetched<45000;for(const m of ['duel','race','coop','swap']){const counts=fresh?liveActivity.modes[m]:null;const label=counts?(counts.waiting===0&&counts.playing===0?'No players waiting · Invite a friend':`${counts.waiting} waiting · ${counts.playing} playing`):'Online count unavailable';$('activity-'+m).textContent=m==='duel'?label:'Friends and practice · Not rated';if(m===mode)$('opponent-activity').textContent=m==='duel'?label:'Friends and practice · Not rated';}const q=fresh?liveActivity.queues:null,line=(x,base)=>!x?base:x.waiting+x.playing===0?base+' · quiet right now':`${base} · ${x.waiting} waiting · ${x.playing} playing`;$('way-competitive-meta').textContent=line(q?.ranked,signedAccount?'Rated':'Rated · sign in to play');$('way-normal-meta').textContent=line(q?.normal,'Not rated');}
async function refreshActivity(){if(activityBusy||document.hidden||state||!['modes','opponent'].includes(step))return;activityBusy=true;try{const response=await fetch('/api/activity',{headers:{authorization:'Bearer '+token},signal:AbortSignal.timeout(8000)});if(!response.ok)throw Error();const data=await response.json();for(const m of ['duel','race','coop','swap']){if(!Number.isSafeInteger(data.modes?.[m]?.waiting)||data.modes[m].waiting<0||!Number.isSafeInteger(data.modes[m].playing)||data.modes[m].playing<0)throw Error();}liveActivity=data;activityFetched=Date.now();}catch{liveActivity=null;}finally{activityBusy=false;renderActivity();}}
